INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spy-vs-spy--1', 9166, '1984-12-31', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2re4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dbxjdf3c4rzrkhl1qoai.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spy vs Spy', 'The black spy and the white spy are out to outsmart each other before the time bell rings. Find the needed objects (money, passport, secret plans and airport door key) by searching rooms in the embassy, which include desks, file cabinets and other furniture. Foil your opponent by setting creative booby traps in the various rooms (a bomb in a dresser drawer, for instance). Traps can be disarmed with objects found in rooms (a water bucket from a firebox on the wall will disarm the bomb in the prior example). When all the items are together in the secret briefcase, head for the airport door.' FROM games WHERE igdb_id = 9166 ON CONFLICT (game_id, language_code) DO NOTHING;
