INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sorcerer', 'Many centuries ago, the Earth was ruled by Sorcerers and Wizards. They possessed mystical powers capable of both good and evil. The most respected influences in the land were from the good Sorcerers. This fact continually disturbed the evil Wizards, and they eventually decided to use their power to conquer the countryside and enslave its people. They devised a plan to systematically eliminate the good Sorcerers by sending wave after wave of diabolical creatures to ravage the world.
