INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skool Daze', 'Skool Daze sets you as Eric, a typical scamp of a schoolboy whose school report is due, and it is so bad that his parents can''t be allowed to see it. This means retrieving it from the headmaster''s safe, by obtaining every piece of the pass-code from the teachers, by hitting each of the shields with your catapult.
