INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Seven Cities of Gold', 'Once, in a tavern on the waterfront, an old salt whispered to you the tale of the Seven Bishops -- Christian men who had been blown far off course into an unknown realm and who established seven Kingdoms whose splendor ranked with the reign of Solomon. Since that time you have dreamed of little else.
