INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Questprobe featuring The Hulk', 'Questprobe featuring The Hulk is a graphic adventure video game. It is the first entry in Questprobe, an intended series of graphic adventure games that only released three instalments before the developer''s bankruptcy. The game''s narrative follows the Marvel superhero Hulk and his human alter-ego Bruce Banner (in their first video game appearance), who must explore the mysterious lair of the Chief Examiner.' FROM games WHERE igdb_id = 12934 ON CONFLICT (game_id, language_code) DO NOTHING;
