INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boulderdash', 'his classic game is about a diamond chase underground with many obstacles. Try - as Rockford - to collect all required diamonds in a total of 16 caves (A-P) each with 5 difficulty levels, and find the exit in the time given. After every 4 caves (D, H, L, P) follows a so-called "intermission", a logical puzzle (without its own "cave letter"). Rockford can dig through the ground and push rocks. But these can also be dangerous. If he stands directly below a rock, Rockford can hold it on his head. But if a rock falls on his head, it will cost him a life. Rocks will not stay on each other or on walls. If Rockford digs away the supporting soil, rocks will start to slide. Furthermore, there are some not-so-friendly animals such as fireflies, amoeba and other things you''d better not touch. Butterflies and other inhabitants of the underground can only be defeated by letting rocks fall on them. When defeated, they turn into diamonds, which Rockford can pick up. As soon as the necessary amount of jewels has been collected (the number is shown in the upper bar), the escape tunnel opens into the next level. Strategy and thoughtful planning is the basis to master this game.' FROM games WHERE igdb_id = 47237 ON CONFLICT (game_id, language_code) DO NOTHING;
