INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('underwurlde', 14588, '1984-12-31', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/otkhjhxkca3qgzxqhyrp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/atwfgttiafggrk6vnpxj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Underwurlde', 'Underwurlde is the second in the Sabreman series, following on from his adventures in Sabre Wulf. The format of the game is a 2D side view flip-screen platform game. The aim is to escape from the Underwurlde via one of the three exits, to go to either Knight Lore, Pentagram or Mire Mare. It was later included in Rare''s 2015 Xbox One retrospective compilation,' FROM games WHERE igdb_id = 14588 ON CONFLICT (game_id, language_code) DO NOTHING;
