INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pitfall II: The Lost Caverns', 'Pitfall II: The Lost Caverns is the sequel to Pitfall and was released for a variety of systems during the mid-1980s including the SG-1000 in 1985. It was also ported to Sega System 1 arcade hardware by Sega. Gameplay is similar to the original game, but the levels are more maze-like.
