INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1984: A Game of Government Management', '84: A Game of Government Management is a financial management game which gives you the chance to be the Chancellor of the Exchequer for the United Kingdom in the 1980s. Starting in 1984 with the real economy figures from 1982/83, you must try to survive in office for as long as possible trying to keep the books balanced and making more money for the country without upsetting too many people.
