INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golf', 'Golf is a game for the NES based on the sport of the same name. The golfer has been identified as Mario in supplemental material, albeit not wearing his traditional shirt and overalls. The gameplay of Golf is relatively simple. The player is given a ball, and a map on the right side of the screen shows the hole that they must hit the ball into. The obstacles on the way are also displayed on the map. The player will get more points depending on how many times they hit the ball to get it into the hole. Many different types of clubs are also available to choose from by pressing Up/Down on the + Control Pad.' FROM games WHERE igdb_id = 3399 ON CONFLICT (game_id, language_code) DO NOTHING;
