INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Grand Prix', 'Feel the excitement of the starting line up and take in the atmosphere before letting your throttle unleash to send your formula one-style vehicle around the courses at incredible speeds! In the amazing World Grand Prix you must battle your way up the pack to snatch pole position and maintain it for as long as possible to whoosh over the finish line first in each race to become the true tarmac racing champion!' FROM games WHERE igdb_id = 29132 ON CONFLICT (game_id, language_code) DO NOTHING;
