INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('clu-clu-land', 7573, '1984-11-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co42t3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ksr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clu Clu Land', 'Are you clever enough to unravel the mystery of Clu Clu Land? The evil Sea Urchin has hidden all the gold in Clu Clu Land in an underground mystery maze. It''s up to you to find the gold before time runs out! But beware. The Sea Urchin will do everything in his power to stop you. He''ll set up traps to trick you, like inviting you into his house where you''ll be swallowed alive! Or bounce you against the Rubber Trap and land you flat on your back! But if you, or you and a friend, can control the Sea Urchin by stunning him with electric shockwaves, you just might find out where he''s hidden the gold and move on to an exciting bonus round!
