INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spartan X', 'Spartan X, known in North America by the Kung-Fu Master port, is a 1984 beat ''em up arcade game developed and published in Japan by Irem. It was later published in North America by Data East, without the movie license. The Japanese version was based on the Jackie Chan movie Wheels on Meals, known as Spartan X in Japan, and credited "Paragon Films Ltd., Towa Promotion", who produced the film upon which it was based. The game is considered by many to be the first beat ''em up video game, and contains elements of Bruce Lee''s Game of Death.' FROM games WHERE igdb_id = 2901 ON CONFLICT (game_id, language_code) DO NOTHING;
