INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boulder Dash', 'Boulder Dash was originally released in 1984 for Atari 8-bit computers. It was developed and published by First Star Software, and spawned a series of sequels, re-releases, and spinoffs. It also did a great deal to establish and influence the mining genre of video games, which can be seen in modern games such as Minecraft, Spelunky, and Terraria.' FROM games WHERE igdb_id = 12942 ON CONFLICT (game_id, language_code) DO NOTHING;
