INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elite', 'Elite is a space trading video game, written and developed by David Braben and Ian Bell and originally published by Acornsoft for the BBC Micro and Acorn Electron computers in September 1984. Elite''s open-ended game model, and revolutionary 3D graphics led to it being ported to virtually every contemporary home computer system, and earned it a place as a classic and a genre maker in gaming history. The game''s title derives from one of the player''s goals of raising their combat rating to the exalted heights of "Elite".
