INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Karateka', 'Karateka is a 1984 beat''em up video game by Jordan Mechner, and was his first game created while attending Yale University. It was originally programmed for the Apple II, and was later ported to several other home computers and early gaming consoles. The game was published in North America by Brøderbund, and in Europe by Ariolasoft.
