INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1942', '1942 is a vertically scrolling shoot ''em up made by Capcom that was released for the arcade in 1984. The goal is to reach Tokyo and destroy the entire Japanese air fleet. The player pilots a plane dubbed the "Super Ace" . The player has to shoot down enemy planes; to avoid enemy fire, the player can perform a roll or "loop-the-loop". During the game the player may collect a series of power-ups, one of them allowing the plane to be escorted by two other smaller fighters in a Tip Tow formation.' FROM games WHERE igdb_id = 6075 ON CONFLICT (game_id, language_code) DO NOTHING;
