INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Hitchhiker''s Guide to the Galaxy', 'The Hitchhiker’s Guide to the Galaxy is a classic Interactive Fiction game. Though divergent from the source material, the main characters, locations, and concepts are here. Unlike the book, death can come quickly if Arthur fails to observe his surroundings, collect inventory, talk to people, and consult the Guide. Don''t panic!' FROM games WHERE igdb_id = 12143 ON CONFLICT (game_id, language_code) DO NOTHING;
