INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Land', 'Pac-Land itself is split into trips. In each of these trips the objective is to get the fairy (that is kept under Pac-man''s hat) to Fairyland and also to return home to Pac-Man''s house. The majority of the trip involves moving from left to right avoiding various obstacles such as the enemy ghosts, water spurts and quicksand traps. Each trip is divided into a number of rounds, the end of which provides Pac-Man with bonus points depending on how much time he has left and also his position in jumping at the end of each round. If the player runs out of time before finishing the round, Sue, the purple ghost, will speed up rapidly.
