INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hydlide', 'An evil demon named Varalys casts a curse upon the princess Ann, turning her into three fairies. You control Sir Jim and set out to find the fairies, and then slay Varalys. Only by vanquishing Varalys can the curse be lifted. Once the princess is restored the kingdom will be saved. The fighting is a little more in-depth than hack and slash. You can either fight with a defensive or offensive stance, or you can use magic spells.' FROM games WHERE igdb_id = 9071 ON CONFLICT (game_id, language_code) DO NOTHING;
