INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Duck Hunt', 'It’s duck season, and your trusty hunting dog is ready to scour the open fields. Test your sharpshooting skills as your targets take flight. Be quick to knock them out of the skies, or your canine companion won’t hesitate to make you the laughingstock of hunters! Need a change in scenery? Best your score against clay-pigeon targets instead!
