INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball', 'Pinball is a game where the player controls the paddles of a virtual pinball machine. The game has two screens to represent the traditional pinball table and one for a bonus mode. Play begins when the player launches a ball with the plunger from first screen through the top of the screen to the second screen. Play will move to the first screen if the ball falls through the bottom of the top screen and will return to the top screen if the ball is hit back through the space at the top of the first screen. If the ball falls through the hole to the right bottom at the top level, the player will enter a mini-game featuring Mario and Lady. The player controls the paddles on either screen to deflect the ball to keep it from falling off the bottom of the lower screen.' FROM games WHERE igdb_id = 86428 ON CONFLICT (game_id, language_code) DO NOTHING;
