INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomb Jack', 'The player controls Jack, a superhero who can leap and glide. Someone has planted 24 bombs at famous tourist sites (the Sphinx and Great Pyramids, the Acropolis, Neuschwanstein Castle in Bavaria, and two cityscapes resembling Miami Beach and Hollywood, which appear only as screen backgrounds rather than unique game locations). Jack must fly around the screen to collect the bombs. Each screen uses a different configuration of platforms upon which Jack may run and jump. Eventually, the levels reoccur a number of times with increasing difficulty.' FROM games WHERE igdb_id = 6100 ON CONFLICT (game_id, language_code) DO NOTHING;
