INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flicky', 'Flicky is an arcade game made by Sega. First released in arcades in 1984, Flicky was also released at the time for the SG-1000, and then ported to the MSX and Japanese computers Sharp X1, Fujitsu FM-7 and NEC PC-8801. It was later ported to the Sega Mega Drive/Genesis in 1991. Flicky was designed by Yoji Ishii, who was with Sonic Team until August 1999, when he formed Artoon, his own company.' FROM games WHERE igdb_id = 6105 ON CONFLICT (game_id, language_code) DO NOTHING;
