INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raid over Moscow', 'Released during the Cold War era, Raid Over Moscow is an action game in which the player (an American space pilot) has to stop three Soviet nuclear attacks on North America, then fight his way into and destroy a nuclear facility located in Moscow''s Kremlin. According to the game''s storyline, the United States is unable to respond to the attack directly due to the dismantlement of its nuclear arsenal.' FROM games WHERE igdb_id = 18168 ON CONFLICT (game_id, language_code) DO NOTHING;
