INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marble Madness', 'Marble Madness is an isometric platform game in which the player manipulates an onscreen marble from a third-person perspective. The player controls the marble''s movements with a trackball, though most home versions use game controllers with directional pads. The aim of the game is for the player to complete six maze-like, isometric race courses before a set amount of time expires. When a player completes a race, the remaining time is added to the next race''s allotted time. The game also allows two players to compete against each other.
