INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('king-s-quest-quest-for-the-crown', 892, '1984-05-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vcm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/skrttpiswjnzxbmg1rmm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King''s Quest: Quest for the Crown', 'King''s Quest: Quest for the Crown is the first game in the King''s Quest series. Players control Sir Graham, a knight of Daventry, who is tasked by King Edward to find three lost treasures to save the kingdom. The game takes place in a fairy tale-inspired world where Graham must explore, solve puzzles, and interact with various characters and creatures. Players navigate Graham through different locations, collecting items and using them to overcome obstacles. The game pioneered the graphic adventure genre, combining text commands with visual elements. As the inaugural title in the series, Quest for the Crown established many of the themes and gameplay elements that would become hallmarks of the King''s Quest franchise, including its fantasy setting, puzzle-solving mechanics, and the character of Graham who would become a central figure in the series'' lore.' FROM games WHERE igdb_id = 892 ON CONFLICT (game_id, language_code) DO NOTHING;
