INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Wings', 'Battle Wings, known in Japan either as B-Wing (ビー・ウィング) or B-Wings (ビー・ウィングズ), is a vertically scrolling shooter first released as an arcade game by Data East in 1984. The game was ported by Data East to the Family Computer in 1986, and was Data East''s very first home release for this platform.
