INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rollerball', 'Pinball is a game loved by people all over the world. And now you can enjoy four of them all rolled into one game! Four different sets of obstavles put a lot of cariety into the game. You have never seen such complicated bounding of the ball. Where will it go? And can you control it? Try your hand at becoing the first player to score a million ppoints, today!' FROM games WHERE igdb_id = 3657 ON CONFLICT (game_id, language_code) DO NOTHING;
