INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyjamarama', 'Pyjamarama is an arcade adventure set across several interconnecting rooms. The player takes the role of Wally, who has gone to bed for the night and has to wake up early in the morning for work. Unfortunately, his alarm clock has not been wound, and thus he will sleep late in the morning, and his boss will fire him. However, in his sleep, Wally''s consciousness travels around his home, and other places, wearing his pyjamas, in search for the key to rewind the alarm clock and wake himself up.' FROM games WHERE igdb_id = 23060 ON CONFLICT (game_id, language_code) DO NOTHING;
