INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hogan''s Alley', 'Hogan''s Alley is a 1984 video game by Nintendo. It was one of the first games to use a light gun as an input device. The game presents players with "cardboard cut-outs" of villains and innocent civilians. The player must shoot the villains and spare the innocent people.' FROM games WHERE igdb_id = 4601 ON CONFLICT (game_id, language_code) DO NOTHING;
